jordan: Go pagination + retry sketch:
```go
// basic pagination using cursor
resp, _ := client.ListEmbeddings(ctx, &ListReq{PageSize: 100})
for resp != nil {
    for _, item := range resp.Items {
        fmt.Println(item.VectorID)
    }
    if resp.NextCursor == "" {
        break
    }
    resp, _ = client.ListEmbeddings(ctx, &ListReq{Cursor: resp.NextCursor})
}

// retry helper (use SDK retry policy when available)
func withRetry(ctx context.Context, fn func() error) error {
    backoff := time.Second
    for i := 0; i < 3; i++ {
        if err := fn(); err == nil {
            return nil
        }
        time.Sleep(backoff)
        backoff *= 2
    }
    return fmt.Errorf("failed after retries")
}
```

